using UnityEngine;

public class CameraHandler : MonoBehaviour
{
    [SerializeField] private float padding = 5f;
    public static CameraHandler Instance;
    
    private void Awake()
    {
        //helps prevent the possibility of having two competing instances of this class
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
    }

    //generated by AI
    //functions to automatically adjust the camera position to fit the puzzle board
    public void FrameObject(GameObject target)
    {
        Renderer renderer = target.GetComponent<Renderer>();

        if (renderer == null)
        {
            Debug.LogWarning("Target has no Renderer.");
            return;
        }

        Bounds bounds = renderer.bounds;

        Camera camera = GetComponent<Camera>();

        float objectHeight = bounds.size.y;
        float objectWidth = bounds.size.x;

        float verticalSize = objectHeight / 2f;

        float horizontalSize = objectWidth / (2f * camera.aspect);

        float requiredSize = Mathf.Max(
            verticalSize,
            horizontalSize
        );

        camera.orthographicSize = requiredSize + padding;

        camera.transform.position = new Vector3(
            bounds.center.x,
            bounds.center.y,
            camera.transform.position.z
        );
    }
}
